  if (plainLanguageEnabled && PLAIN_COPY[currentLanguage]?.[key]) return PLAIN_COPY[currentLanguage][key];
  return COPY[currentLanguage]?.[key] || UI_COPY[currentLanguage]?.[key] || LANGUAGE_PATCHES[currentLanguage]?.[key] || STATUS_COPY[currentLanguage]?.[key] || COPY.en[key] || UI_COPY.en[key] || LANGUAGE_PATCHES.en?.[key] || STATUS_COPY.en[key] || PLAIN_LABELS[currentLanguage]?.[key] || PLAIN_LABELS.en[key] || EXTRA_COPY[key] || key;
