function escapeHtml(value) { return String(value).replace(/[&<>'"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", "'": "&#39;", '"': "&quot;" }[c])); }
function announce(message) { const region = $("#live-region"); if (region) region.textContent = message; }
function showToast(message) { const toast = $("#toast"); toast.textContent = message; toast.classList.add("show"); window.clearTimeout(showToast.timer); showToast.timer = window.setTimeout(() => toast.classList.remove("show"), 3200); announce(message); }
function setBusy(button, busy) { if (!button) return; button.disabled = busy; button.setAttribute("aria-busy", String(busy)); button.classList.toggle("is-busy", busy); }

function updatePlainLanguageControl() {
  const button = $("#plain-language-toggle");
  const status = $("#plain-language-status");
  if (!button) return;
  button.setAttribute("aria-pressed", String(plainLanguageEnabled));
  button.classList.toggle("is-active", plainLanguageEnabled);
  const label = button.querySelector("[data-plain-label]");
  if (label) label.textContent = t(plainLanguageEnabled ? "plainLanguageOff" : "plainLanguageOn");
  button.setAttribute("aria-label", t(plainLanguageEnabled ? "plainLanguageOff" : "plainLanguageOn"));
  button.title = t(plainLanguageEnabled ? "plainLanguageOff" : "plainLanguageOn");
  if (status) status.textContent = t(plainLanguageEnabled ? "plainLanguageStatusOn" : "plainLanguageStatusOff");
}

function updateConnectionStatus() {
  const element = $("#connection-status");
  if (!element) return;
  const online = navigator.onLine;
  element.textContent = t(online ? "connectionOnline" : "connectionOffline");
  element.classList.toggle("is-offline", !online);
}

function setPlainLanguage(enabled) {
  plainLanguageEnabled = Boolean(enabled);
  localStorage.setItem("janration-plain-language", String(plainLanguageEnabled));
  document.body.classList.toggle("plain-language", plainLanguageEnabled);
  applyLanguage(currentLanguage);
  announce(t(plainLanguageEnabled ? "plainLanguageStatusOn" : "plainLanguageStatusOff"));
}

function applyLanguage(language) {
  currentLanguage = COPY[language] ? language : "en";
  localStorage.setItem("janration-language", currentLanguage);
  document.documentElement.lang = currentLanguage;
  document.title = "JanRation";
  document.querySelectorAll("[data-i18n]").forEach((element) => { element.innerHTML = t(element.dataset.i18n); });
  document.querySelectorAll("[data-i18n-placeholder]").forEach((element) => { element.placeholder = t(element.dataset.i18nPlaceholder); });
  $("#language-select").value = currentLanguage;
  updatePlainLanguageControl();
  updateConnectionStatus();
  if (currentProfile) renderDashboard(currentProfile);
  renderComplaints(window.complaintData || SYNTHETIC.complaints);
  renderShops();
}

function openModal(id) { const modal = $(id); if (!modal) return; modal.hidden = false; document.body.classList.add("modal-open"); const focusTarget = modal.querySelector("input, button:not(.modal-close), select, textarea"); if (focusTarget) window.setTimeout(() => focusTarget.focus(), 30); }
function closeModal(id) { const modal = $(id); if (modal) modal.hidden = true; if (![...document.querySelectorAll(".modal-backdrop")].some((item) => !item.hidden)) document.body.classList.remove("modal-open"); }

function authReferenceView(prefill = "") { return `<div class="auth-content"><p class="eyebrow">01 / 02</p><h2 id="auth-title">${t("authTitle")}</h2><p>${t("authReferenceHelp")}</p><form class="auth-form" id="auth-reference-form"><label>${t("authReference")}<input id="auth-reference" value="${escapeHtml(prefill)}" autocomplete="off" placeholder="DEMO-7824" required /></label><button class="button button-primary" type="submit">${t("authContinue")} →</button></form><button class="demo-chip" type="button" id="auth-demo-fill">${t("authUseDemo")}</button><p class="helper">${t("demoSmsNote")}</p><p class="auth-error" id="auth-error" aria-live="polite"></p></div>`; }
function authOTPView(destination, otp) { return `<div class="auth-content"><p class="eyebrow">02 / 02</p><h2>${t("authOtpTitle")}</h2><p>${t("authOtpHelp")} ${t("otpDestination")} <strong>${escapeHtml(destination)}</strong></p><form class="auth-form" id="auth-otp-form"><label>${t("otpLabel")}<input id="auth-otp" inputmode="numeric" maxlength="6" pattern="[0-9]{6}" autocomplete="one-time-code" placeholder="246810" required /></label><button class="button button-primary" type="submit">${t("authVerify")} →</button></form><div class="demo-otp"><span>${t("demoOtpLabel")}</span><strong>${escapeHtml(otp)}</strong></div><button class="back-button" type="button" id="auth-back">← ${t("authBack")}</button><p class="auth-error" id="auth-error" aria-live="polite"></p></div>`; }

function openAuth(prefill = "") { $("#auth-content").innerHTML = authReferenceView(prefill); $("#auth-step-one").className = "is-active"; $("#auth-step-two").className = ""; openModal("#auth-modal"); bindAuthReference(); }
function bindAuthReference() { $("#auth-demo-fill").addEventListener("click", () => { $("#auth-reference").value = "DEMO-7824"; $("#auth-reference").focus(); }); $("#auth-reference-form").addEventListener("submit", async (event) => { event.preventDefault(); const button = event.currentTarget.querySelector("button[type=submit]"); const reference = $("#auth-reference").value; setBusy(button, true); let payload; try { const response = await fetch("/api/auth/request-otp", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ card_reference: reference }) }); payload = await response.json(); } catch { payload = { ok: normalise(reference) === "DEMO-7824", challenge_id: "local-demo", masked_destination: "+91 •••••• 0198 (demo only)", demo_otp: "246810", message: "Local demo fallback" }; } setBusy(button, false); if (!payload.ok) { $("#auth-error").textContent = t("authGenericError"); return; } challengeId = payload.challenge_id; $("#auth-content").innerHTML = authOTPView(payload.masked_destination, payload.demo_otp || "246810"); $("#auth-step-one").className = "is-complete"; $("#auth-step-two").className = "is-active"; bindAuthOTP(payload.demo_otp || "246810"); }); }
function normalise(value) { return String(value).trim().toUpperCase().replace(/\s/g, ""); }
function bindAuthOTP(fallbackOTP) { $("#auth-back").addEventListener("click", () => openAuth($("#auth-reference")?.value || "DEMO-7824")); $("#auth-otp-form").addEventListener("submit", async (event) => { event.preventDefault(); const button = event.currentTarget.querySelector("button[type=submit]"); const otp = $("#auth-otp").value; setBusy(button, true); let payload; try { const response = await fetch("/api/auth/verify-otp", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ challenge_id: challengeId, otp }) }); payload = await response.json(); } catch { payload = { ok: otp === fallbackOTP || otp === "246810", session_token: "local-demo-session" }; } setBusy(button, false); if (!payload.ok) { $("#auth-error").textContent = payload.message || t("otpGenericError"); return; } if (payload.session_token) sessionStorage.setItem("janration-session", payload.session_token); closeModal("#auth-modal"); await loadDashboard(payload.session_token || "local-demo-session"); }); }

function initialiseAccountPreview() { const section = $("#account-view"); if (!section) return; section.hidden = false; section.classList.remove("is-ready"); const dashboard = section.querySelector(".dashboard-grid"); const history = section.querySelector(".transactions-card"); if (dashboard) dashboard.hidden = true; if (history) history.hidden = true; const logout = $("#logout-button"); if (logout) logout.hidden = true; if (!$("#account-empty")) { const empty = document.createElement("div"); empty.className = "account-empty"; empty.id = "account-empty"; empty.innerHTML = `<strong>${escapeHtml(t("accountPreviewTitle"))}</strong><p>${escapeHtml(t("accountPreviewText"))}</p><button class="small-button" type="button" data-action="open-auth"><span>${escapeHtml(t("accountPreviewCta"))}</span> →</button>`; section.querySelector(".section-heading").after(empty); } }
function initialiseOnorcExplainer() { const copy = $("#how-it-works .portability-copy"); if (!copy || $("#onorc-explainer")) return; const explainer = document.createElement("div"); explainer.className = "onorc-explainer"; explainer.id = "onorc-explainer"; explainer.innerHTML = `<strong>${escapeHtml(t("onorcTitle"))}</strong><p>${escapeHtml(t("onorcText"))}</p>`; copy.querySelector(".text-button")?.before(explainer); }
async function loadDashboard(token) { let profile; try { const response = await fetch(`/api/dashboard?session_token=${encodeURIComponent(token)}`); if (!response.ok) throw new Error("dashboard unavailable"); profile = (await response.json()).data; } catch { profile = SYNTHETIC.profile; } currentProfile = profile; $("#login-card").hidden = true; $("#account-view").hidden = false; $("#account-view").classList.add("is-ready"); $("#account-empty").hidden = true; $("#account-view .dashboard-grid").hidden = false; $("#account-view .transactions-card").hidden = false; $("#logout-button").hidden = false; renderDashboard(profile); $("#account-view").scrollIntoView({ behavior: "smooth", block: "start" }); announce(t("dashboardTitle")); }
function renderDashboard(profile) { $("#profile-summary").textContent = `${profile.masked_household} · ${profile.category} · ${profile.member_count} ${t("memberCount")} · ${profile.state}`; $("#last-updated").textContent = `${t("updated")} ${profile.last_updated}`; $("#allocation-bars").innerHTML = profile.allocations.map((item) => { const percent = Math.round((item.withdrawn / item.total) * 100); const label = localiseInventoryItem(item.name); return `<div class="allocation-row"><div class="allocation-label"><span>${escapeHtml(label)}</span><span>${item.remaining} ${item.unit} ${t("left")}</span></div><div class="bar-track"><div class="bar-fill ${item.color}" style="width:${percent}%" role="progressbar" aria-label="${escapeHtml(label)} ${t("withdrawn")}" aria-valuenow="${percent}" aria-valuemin="0" aria-valuemax="100"></div></div><div class="allocation-meta"><span>${item.withdrawn} ${item.unit} ${t("withdrawn")}</span><span>${item.total} ${item.unit} ${t("of")}</span></div></div>`; }).join(""); $("#notices-list").innerHTML = profile.notices.map((notice) => `<div class="notice"><span class="notice-icon">${notice.type === "tip" ? "✓" : "i"}</span><strong>${escapeHtml(notice.title)}</strong><p>${escapeHtml(notice.text)}</p></div>`).join(""); renderTransactions(profile.transactions); }
function renderTransactions(transactions) { const visible = showingAllHistory ? transactions : transactions.slice(0, 3); $("#transactions-list").innerHTML = visible.map((item) => `<div class="transaction-row"><time>${escapeHtml(item.date)}</time><div><strong>${escapeHtml(item.shop)}</strong><small>${escapeHtml(item.items)} · ${escapeHtml(item.reference)}</small></div><span class="transaction-status">${item.status === "No deduction" ? t("noDeduction") : t("completed")}</span></div>`).join(""); $("#history-toggle").setAttribute("aria-expanded", String(showingAllHistory)); $("#history-toggle span").textContent = showingAllHistory ? "Show less" : t("viewAll"); }

async function loadShops() { const state = $("#shop-state").value; const district = $("#shop-district").value.trim().toLowerCase(); const onorc = $("#onorc-filter").checked; const button = $("#find-shops-button"); setBusy(button, true); let shops; try { const params = new URLSearchParams(); if (state !== "all") params.set("state", state); if (district) params.set("district", district); if (onorc) params.set("onorc_only", "true"); const response = await fetch(`/api/shops?${params}`); if (!response.ok) throw new Error(); shops = (await response.json()).shops; } catch { shops = SYNTHETIC.shops.filter((shop) => (state === "all" || shop.state === state) && (!district || shop.district.toLowerCase().includes(district)) && (!onorc || shop.onorc_enabled)); } setBusy(button, false); currentShops = shops; if (!shops.some((shop) => shop.id === selectedShopId)) selectedShopId = shops[0]?.id || null; renderShops(); }
function localiseShopStatus(status) { return status === "Opening soon" ? t("shopOpeningSoon") : t("shopOpenToday"); }
function localiseShopDate(value) { const source = String(value); const labels = SHOP_DATE_COPY[currentLanguage] || SHOP_DATE_COPY.en; if (source.startsWith("Today")) return `${labels.today}${source.slice(5)}`; if (source.startsWith("Yesterday")) return `${labels.yesterday}${source.slice(9)}`; return source; }
function localiseShopStock(note) { const source = String(note).toLowerCase(); if (source.includes("all listed")) return t("shopAllItemsAvailable"); if (source.includes("last stock")) return t("shopLastRiceAvailable"); const items = [["rice", "itemRice"], ["wheat", "itemWheat"], ["dal", "itemDal"], ["sugar", "itemSugar"]].filter(([name]) => source.includes(name)).map(([, key]) => t(key)); return `${items.join(", ")} ${t("shopReportedAvailable")}`; }
function localiseInventoryItem(name) { return { Rice: t("itemRice"), Wheat: t("itemWheat"), "Toor dal": t("itemDal"), Sugar: t("itemSugar") }[name] || name; }
function localiseInventoryValue(value) { return { High: t("inventoryHigh"), Medium: t("inventoryMedium"), Low: t("inventoryLow") }[value] || value; }
function shopCard(shop) { const access = shop.wheelchair_accessible ? t("shopStepFree") : t("shopAskAccess"); const onorc = shop.onorc_enabled ? t("shopOnorc") : t("shopHomeState"); return `<button class="shop-card ${shop.id === selectedShopId ? "is-selected" : ""}" type="button" data-store-id="${escapeHtml(shop.id)}"><div class="shop-card-main"><div class="shop-card-title"><h4>${escapeHtml(shop.name)}</h4><strong>${escapeHtml(shop.distance)}</strong></div><p>${escapeHtml(shop.address)}</p><p>${escapeHtml(shop.hours)}</p><div class="shop-tags"><span>${access}</span><span>${onorc}</span></div></div><div class="shop-meta"><span class="shop-open">${escapeHtml(localiseShopStatus(shop.status))}</span><span>${shop.queue_minutes} ${t("shopQueue")}</span><span>${t("shopStock")}: ${escapeHtml(localiseShopDate(shop.stock_updated))}</span><span>${escapeHtml(localiseShopStock(shop.stock_note))}</span><span>${escapeHtml(shop.reference)}</span></div></button>`; }
function renderShops() { $("#shop-list").innerHTML = currentShops.length ? currentShops.map(shopCard).join("") : `<p class="empty-state">${t("emptyShops")}</p>`; $("#complaint-count").textContent = (window.complaintData || SYNTHETIC.complaints).length; $("#map-markers").innerHTML = currentShops.map((shop) => `<button class="map-marker ${shop.id === selectedShopId ? "is-selected" : ""}" type="button" data-store-id="${escapeHtml(shop.id)}" style="left:${shop.map_x}%;top:${shop.map_y}%" aria-label="Select ${escapeHtml(shop.name)}"><span>ज</span></button>`).join(""); const selected = currentShops.find((shop) => shop.id === selectedShopId); if (selected) { $("#selected-shop").hidden = false; $("#selected-shop").innerHTML = `<h3>${escapeHtml(selected.name)}</h3><p>${escapeHtml(selected.address)} · ${escapeHtml(selected.hours)}</p><div class="inventory-list">${selected.inventory.map((item) => `<span>${escapeHtml(localiseInventoryItem(item.name))}: ${escapeHtml(localiseInventoryValue(item.available))}</span>`).join("")}</div><p>${escapeHtml(localiseShopStock(selected.stock_note))} · ${t("shopLastReport")} ${escapeHtml(localiseShopDate(selected.stock_updated))}</p><button class="small-button" type="button" data-action="copy-store" data-store-reference="${escapeHtml(selected.reference)}">${t("shopCopyReference")}</button>`; } else $("#selected-shop").hidden = true; }
function selectShop(id) { if (!currentShops.some((shop) => shop.id === id)) return; selectedShopId = id; renderShops(); }

async function loadComplaints() { let complaints; try { const response = await fetch("/api/complaints"); if (!response.ok) throw new Error(); complaints = (await response.json()).complaints; } catch { complaints = SYNTHETIC.complaints; } window.complaintData = complaints; renderComplaints(complaints); }
function localiseComplaintCategory(category) { return { "Shop was closed": t("complaintShopClosed"), "Quantity was incorrect": t("complaintQuantity"), "Authentication failed": t("complaintAuth"), "Card or member update": t("complaintCard") }[category] || category; }
function renderComplaints(complaints) { if (!$("#complaints-list")) return; $("#complaint-count").textContent = complaints.length; $("#complaints-list").innerHTML = complaints.map((item) => `<article class="complaint-row"><div><h4>${escapeHtml(localiseComplaintCategory(item.category))}</h4><p><strong>${escapeHtml(item.ticket)}</strong> · ${escapeHtml(item.shop)} · ${escapeHtml(item.created)}</p><p>${escapeHtml(item.update)}</p></div><div class="complaint-meta"><span class="complaint-status ${escapeHtml(item.status_key)}">${t(item.status_key)}</span></div></article>`).join(""); }
function openComplaintForm() { const card = $("#new-complaint-card"); card.hidden = false; card.scrollIntoView({ behavior: "smooth", block: "nearest" }); $("#complaint-description").focus(); }
async function submitComplaint(event) { event.preventDefault(); const button = event.currentTarget.querySelector("button[type=submit]"); const payload = { category: $("#complaint-category").value, description: $("#complaint-description").value, store_reference: $("#complaint-store").value }; setBusy(button, true); let data; try { const response = await fetch("/api/complaints", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(payload) }); if (!response.ok) throw new Error(); data = await response.json(); } catch { data = { complaint: { ticket: `JR-${Math.random().toString(16).slice(2, 8).toUpperCase()}`, category: payload.category, shop: payload.store_reference || "Not specified", created: "Today", status: "Submitted", status_key: "submitted", update: "Your synthetic complaint has been queued for the district office. Next update within 3 working days." } }; } setBusy(button, false); window.complaintData = [data.complaint, ...(window.complaintData || SYNTHETIC.complaints)]; renderComplaints(window.complaintData); event.currentTarget.reset(); $("#new-complaint-card").hidden = true; showToast(`${t("complaintSuccess")} ${data.complaint.ticket}`); }

function openInfoModal(type) { const titles = { limitations: t("limitationsModalTitle"), privacy: t("privacyModalTitle"), support: t("supportModalTitle"), accessibility: t("accessibilityTitle") }; const bodies = { limitations: `<p>JanRation is a safe, self-contained prototype. It does not connect to live government systems, validate eligibility, issue ration cards, send real SMS, use Aadhaar, process payments, or guarantee shop stock.</p><p>Shop locations, balances, transactions, OTPs, tickets, and timestamps are synthetic. Production work still requires state agreements, security review, legal review, accessibility QA, translation review, and operational ownership.</p>`, privacy: `<p>This prototype keeps identity deliberately small: only a demo reference and a short-lived synthetic session are used. No real Aadhaar, biometrics, OTP delivery, payment details, or phone numbers are collected.</p><p>A production service should use consent, tokenization, purpose limitation, encryption, retention controls, audit logs, and state-owned identity boundaries.</p>`, support: `<p>For a real service, support should be available through the local help desk, phone, SMS, IVR, and assisted digital centres. Keep your ticket reference and ask for the next update date.</p><p>In this demo, all tickets are synthetic and remain only in the running application.</p>`, accessibility: `<p>JanRation supports keyboard navigation, a skip link, visible focus, screen-reader announcements, high contrast, reduced motion, responsive layouts, and a listen control for the household summary.</p><p>Use the language menu to translate the page, and select the contrast button for stronger color contrast. The listen control stops when clicked again.</p>` }; $("#info-title").textContent = titles[type] || t("helpModalTitle"); $("#info-body").innerHTML = bodies[type] || bodies.limitations; openModal("#info-modal"); }
function openPortability() { $("#info-title").textContent = t("portabilityModalTitle"); $("#info-body").innerHTML = `<p>${t("portabilityIntro")}</p><form class="auth-form" id="portability-form"><label>${t("portabilityHome")}<select id="portability-home"><option value="Tamil Nadu">${t("stateTamilNadu")}</option><option value="Maharashtra">${t("stateMaharashtra")}</option><option value="Karnataka">${t("stateKarnataka")}</option></select></label><label>${t("portabilityCurrent")}<select id="portability-current"><option value="Maharashtra">${t("stateMaharashtra")}</option><option value="Tamil Nadu">${t("stateTamilNadu")}</option><option value="Jammu and Kashmir">${t("stateJammuKashmir")}</option></select></label><button class="button button-primary" type="submit">${t("portabilityCta")} →</button></form><div id="portability-result"></div>`; openModal("#info-modal"); $("#portability-form").addEventListener("submit", async (event) => { event.preventDefault(); const params = new URLSearchParams({ home_state: $("#portability-home").value, current_state: $("#portability-current").value }); let data; try { const response = await fetch(`/api/portability?${params}`); data = await response.json(); } catch { data = { message: "Your home-state entitlement can be used at an ONORC-enabled shop here.", steps: ["Carry your ration card or state-approved reference.", "Ask for an ONORC-enabled Fair Price Shop.", "Check the quantity and price shown on the POS screen before confirming."], shop_reference: "MH-PUN-2408" }; } $("#portability-result").innerHTML = `<div class="portability-result"><strong>${escapeHtml(data.message)}</strong><ol>${data.steps.map((step, index) => `<li>${escapeHtml(t(["portabilityStep1", "portabilityStep2", "portabilityStep3"][index]) || step)}</li>`).join("")}</ol><p class="muted">${t("portabilitySuggested")} ${escapeHtml(data.shop_reference)}</p></div>`; }); }

document.addEventListener("click", (event) => { const actionElement = event.target.closest("[data-action]"); const storeElement = event.target.closest("[data-store-id]"); if (storeElement) { event.preventDefault(); selectShop(storeElement.dataset.storeId); return; } if (!actionElement) return; event.preventDefault(); const action = actionElement.dataset.action; if (action === "open-auth") openAuth(actionElement.dataset.demo ? "DEMO-7824" : ""); if (action === "open-portability") openPortability(); if (action === "new-complaint") openComplaintForm(); if (action === "cancel-complaint") $("#new-complaint-card").hidden = true; if (action === "copy-store") { navigator.clipboard?.writeText(actionElement.dataset.storeReference); showToast(`${t("copyReady")}: ${actionElement.dataset.storeReference}`); } });
$("#language-select").addEventListener("change", (event) => applyLanguage(event.target.value));
$("#plain-language-toggle").addEventListener("click", () => setPlainLanguage(!plainLanguageEnabled));
$("#contrast-toggle").addEventListener("click", () => { const enabled = document.body.classList.toggle("high-contrast"); localStorage.setItem("janration-contrast", String(enabled)); });
$("#history-toggle").addEventListener("click", () => { showingAllHistory = !showingAllHistory; if (currentProfile) renderTransactions(currentProfile.transactions); });
function speechValues(profile) { const allocations = Object.fromEntries(profile.allocations.map((item) => [item.name.toLowerCase().replace(/\s+/g, "_"), item])); return { rice: allocations.rice?.total ?? 0, wheat: allocations.wheat?.total ?? 0, dal: allocations.toor_dal?.total ?? 0, sugar: allocations.sugar?.total ?? 0, withdrawnRice: allocations.rice?.withdrawn ?? 0 }; }
function preferredSpeechVoice(locale) { const voices = window.speechSynthesis.getVoices(); const target = locale.toLowerCase(); const language = currentLanguage.toLowerCase(); return voices.find((voice) => voice.lang.toLowerCase() === target) || voices.find((voice) => voice.lang.toLowerCase().startsWith(language)) || voices.find((voice) => voice.lang.toLowerCase().startsWith(target.slice(0, 2))) || null; }
function readRation() { const feedback = READER_FEEDBACK[currentLanguage] || READER_FEEDBACK.en; if (!("speechSynthesis" in window) || typeof SpeechSynthesisUtterance === "undefined") { showToast(feedback.unsupported); return; } const locale = SPEECH_LOCALES[currentLanguage] || SPEECH_LOCALES.en; const profile = currentProfile || SYNTHETIC.profile; const text = (SPEECH_COPY[currentLanguage] || SPEECH_COPY.en)(speechValues(profile)); const utterance = new SpeechSynthesisUtterance(text); utterance.lang = locale; const voice = preferredSpeechVoice(locale); if (voice) utterance.voice = voice; utterance.rate = .92; utterance.pitch = 1; window.speechSynthesis.cancel(); window.speechSynthesis.speak(utterance); showToast(feedback.started); }
$("#listen-button").addEventListener("click", () => { if (window.speechSynthesis?.speaking) { window.speechSynthesis.cancel(); showToast(t("listenStopped")); } else readRation(); });
$("#logout-button").addEventListener("click", () => { sessionStorage.removeItem("janration-session"); currentProfile = null; $("#login-card").hidden = false; initialiseAccountPreview(); showToast(t("signOut")); });
$("#find-shops-button").addEventListener("click", loadShops); $("#shop-state").addEventListener("change", loadShops); $("#onorc-filter").addEventListener("change", loadShops); $("#shop-district").addEventListener("keydown", (event) => { if (event.key === "Enter") loadShops(); });
$("#complaint-form").addEventListener("submit", submitComplaint);
document.addEventListener("click", (event) => { const accessibilityLink = event.target.closest('.footer-links a[href="#how-it-works"]'); if (accessibilityLink) { event.preventDefault(); openInfoModal("accessibility"); return; } const modalTrigger = event.target.closest("[data-modal]"); if (modalTrigger) openInfoModal(modalTrigger.dataset.modal); const closer = event.target.closest("[data-close-modal]"); if (closer) closeModal(`#${closer.dataset.closeModal}`); if (event.target.classList.contains("modal-backdrop")) closeModal(`#${event.target.id}`); });
window.addEventListener("online", () => { updateConnectionStatus(); showToast(t("connectionOnline")); }); window.addEventListener("offline", () => { updateConnectionStatus(); showToast(t("connectionOffline")); });

if (plainLanguageEnabled) document.body.classList.add("plain-language");
if (localStorage.getItem("janration-contrast") === "true") document.body.classList.add("high-contrast");
applyLanguage(currentLanguage); initialiseAccountPreview(); initialiseOnorcExplainer(); renderShops(); loadComplaints();
